/* Tech Robot · unitat 2 «Repeteix!» (bucles i patrons) */
Object.assign(TBADGE, {
  bucle: { id: 'bucle', ico: '🔁', n: 'Mestre/a dels bucles|Maestro/a de los bucles', d: 'Has fet servir el bloc «Repeteix» per no posar blocs repetits.|Has usado el bloque «Repite» para no poner bloques repetidos.' },
  patro: { id: 'patro', ico: '🔍', n: 'Detectiu/iva de patrons|Detective de patrones', d: "Has trobat el tros que es repeteix i l'has posat dins d'un bucle.|Has encontrado el trozo que se repite y lo has puesto dentro de un bucle." },
  mosaic: { id: 'mosaic', ico: '🎨', n: 'Artista del mosaic|Artista del mosaico', d: 'Projecte acabat: has pintat un mosaic amb bucles.|Proyecto terminado: has pintado un mosaico con bucles.' }
});
ROBOT_UNITS[2] = { t: 'Repeteix!|¡Repite!', d: 'Bucles i patrons|Bucles y patrones', color: '#20A464', s: [
  /* ---------- Sessió 1 · Repetir sense cansar-se ---------- */
  { id: 'r2-1', t: 'Repetir sense cansar-se|Repetir sin cansarse', min: 35, badge: 'bucle',
    learn: ["Un <b>bucle</b> repeteix els blocs de dins tantes vegades com diu el número.|Un <b>bucle</b> repite los bloques de dentro tantas veces como dice el número.",
      'Per saber el número, compta quantes vegades es repeteix el mateix bloc.|Para saber el número, cuenta cuántas veces se repite el mismo bloque.',
      'Amb un bucle, el programa és més curt i costa menys equivocar-se.|Con un bucle, el programa es más corto y cuesta menos equivocarse.'],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'Recordes la unitat anterior? Què vol dir <b>descompondre</b> un problema?|¿Recuerdas la unidad anterior? ¿Qué quiere decir <b>descomponer</b> un problema?',
        opts: ['Partir-lo en trossos més petits|Partirlo en trozos más pequeños', 'Fer-lo més llarg|Hacerlo más largo', 'Esborrar-lo i començar de nou|Borrarlo y empezar de nuevo'], a: 0 },
      { k: 'quiz', ph: 'recorda', w: { map: ['.....', '>###F'] }, q: 'Quants blocs <b>Endavant</b> calen perquè en Bit arribi a la bandera?|¿Cuántos bloques <b>Adelante</b> hacen falta para que Bit llegue a la bandera?',
        opts: ['4', '5', '3'], a: 0, ex: 'Compta els salts, no la casella on ja és en Bit: 1, 2, 3, 4.|Cuenta los saltos, no la casilla donde ya está Bit: 1, 2, 3, 4.' },
      { k: 'story', ph: 'missio', who: 'both', scene: 'illa', title: 'El missatge del far|El mensaje del faro', t: "Avui en Bit té una missió important: portar un missatge a la guarda del <b>far</b>, a l'altra punta de l'illa. El camí és llarg, molt llarg… i gairebé tot recte!|Hoy Bit tiene una misión importante: llevar un mensaje a la guardiana del <b>faro</b>, en la otra punta de la isla. El camino es largo, muy largo… ¡y casi todo recto!" },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'think', w: { map: ['.......', '>#####F', '.......'] }, blocks: ['rep'],
        t: "BIP… Endavant, Endavant, Endavant, Endavant, Endavant, Endavant… Uf! Posar tants blocs iguals és pesat. I si me'n descompto? Necessito una ordre nova: <b>Repeteix</b>.|BIP… Adelante, Adelante, Adelante, Adelante, Adelante, Adelante… ¡Uf! Poner tantos bloques iguales es pesado. ¿Y si me descuento? Necesito una orden nueva: <b>Repite</b>." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'A la vida|En la vida', t: 'Repetim coses cada dia|Repetimos cosas cada día', anim: 'u2life',
          x: "Moltes coses de cada dia són <b>repeticions</b>: aplaudir tres vegades, pujar els graons d'una escala, cantar la tornada d'una cançó… Fem el mateix, una vegada i una altra.|Muchas cosas de cada día son <b>repeticiones</b>: aplaudir tres veces, subir los peldaños de una escalera, cantar el estribillo de una canción… Hacemos lo mismo, una vez y otra." },
        { k: 'Repetir cansa|Repetir cansa', t: 'Massa blocs iguals|Demasiados bloques iguales', anim: 'u2tired',
          x: "Si en Bit ha d'avançar 7 caselles, li calen 7 blocs Endavant. És llarg de fer, costa de llegir i és fàcil <b>descomptar-se</b>. Hi ha una manera molt més curta!|Si Bit tiene que avanzar 7 casillas, le hacen falta 7 bloques Adelante. Es largo de hacer, cuesta de leer y es fácil <b>descontarse</b>. ¡Hay una manera mucho más corta!" },
        { k: 'Bucle|Bucle', t: 'El bloc «Repeteix»|El bloque «Repite»', demo: { w: { map: ['.......', '>#####F', '.......'] }, prog: TP('6{ f }') },
          x: "El bloc <b>Repeteix N vegades</b> fa els blocs que té <b>a dins</b> tantes vegades com diu el número. Un bloc que repeteix es diu <span class='hl'>bucle</span>. Aquí, amb només 2 blocs, en Bit avança 6 caselles.|El bloque <b>Repite N veces</b> hace los bloques que tiene <b>dentro</b> tantas veces como dice el número. Un bloque que repite se llama <span class='hl'>bucle</span>. Aquí, con solo 2 bloques, Bit avanza 6 casillas.",
          tip: 'Per canviar el número, toca el bucle i fes servir els botons − i +.|Para cambiar el número, toca el bucle y usa los botones − y +.' },
        { k: 'Per dins|Por dentro', t: 'Com compta un bucle|Cómo cuenta un bucle', anim: 'u2loop',
          x: "El bucle fa els blocs de dins, de dalt a baix. Quan arriba al final, <b>torna a començar</b> i compta una volta més. Quan ha fet totes les voltes, s'acaba i en Bit continua amb el bloc de sota del bucle.|El bucle hace los bloques de dentro, de arriba abajo. Cuando llega al final, <b>vuelve a empezar</b> y cuenta una vuelta más. Cuando ha hecho todas las vueltas, se termina y Bit sigue con el bloque de debajo del bucle." },
        { k: 'Compte!|¡Cuidado!', t: 'El número ha de ser exacte|El número tiene que ser exacto', demo: { w: { map: ['......', '>###FR', '......'] }, prog: TP('5{ f }'), speed: 900 },
          x: "Aquí el bucle diu 5, però la bandera és a 4 caselles: en Bit se'n passa i xoca amb la roca. Si el número és massa gran, se'n passa; si és massa petit, no hi arriba.|Aquí el bucle dice 5, pero la bandera está a 4 casillas: Bit se pasa y choca con la roca. Si el número es demasiado grande, se pasa; si es demasiado pequeño, no llega.",
          bad: 'Comptar també la casella on ja és en Bit.|Contar también la casilla donde ya está Bit.', good: 'Comptar només els salts: un per cada casella nova.|Contar solo los saltos: uno por cada casilla nueva.' }
      ] },
      { k: 'quiz', ph: 'mans', q: 'Mira aquest programa: <b>Endavant, Endavant, Endavant, Endavant, Endavant</b>. Com el pots escriure amb un bucle?|Mira este programa: <b>Adelante, Adelante, Adelante, Adelante, Adelante</b>. ¿Cómo lo puedes escribir con un bucle?',
        opts: ['Repeteix 5 vegades: Endavant|Repite 5 veces: Adelante', 'Repeteix 4 vegades: Endavant|Repite 4 veces: Adelante', 'Repeteix 5 vegades: Endavant, Endavant|Repite 5 veces: Adelante, Adelante'], a: 0,
        ex: "Hi ha 5 Endavant iguals: el bucle fa 5 vegades un sol Endavant. Amb dos Endavant a dins, en Bit n'avançaria 10!|Hay 5 Adelante iguales: el bucle hace 5 veces un solo Adelante. ¡Con dos Adelante dentro, Bit avanzaría 10!" },
      { k: 'unplug', ph: 'mans', ico: '🔁', title: 'El bucle del cos|El bucle del cuerpo', t: 'Amb algú de casa, feu de robot i de programador/a:|Con alguien de casa, haced de robot y de programador/a:',
        steps: ['Inventeu un moviment curt: per exemple, <b>un salt i un aplaudiment</b>.|Inventad un movimiento corto: por ejemplo, <b>un salto y un aplauso</b>.',
          "El programador/a diu el bucle: «<b>Repeteix 4 vegades</b>: salta i aplaudeix».|El programador/a dice el bucle: «<b>Repite 4 veces</b>: salta y aplaude».",
          'El robot ho fa i compta les voltes en veu alta: «una, dues, tres, quatre». Quan arriba al número, para!|El robot lo hace y cuenta las vueltas en voz alta: «una, dos, tres, cuatro». ¡Cuando llega al número, para!',
          'Canvieu el número i el moviment, i després canvieu els papers.|Cambiad el número y el movimiento, y después cambiad los papeles.'],
        tip: "Si el robot fa una volta de més o de menys, no passa res: és com un bug del bucle. Torneu-ho a provar!|Si el robot hace una vuelta de más o de menos, no pasa nada: es como un bug del bucle. ¡Volved a probarlo!" },
      { k: 'predict', ph: 'prova', q: 'En Bit fa aquest bucle. <b>On acabarà?</b> Tria A, B o C.|Bit hace este bucle. <b>¿Dónde terminará?</b> Elige A, B o C.',
        w: { map: ['.......', '>#A#B#C'] }, prog: TP('2{ f f }'), a: 'B', ex: 'El bucle fa 2 vegades «Endavant, Endavant»: són 4 caselles.|El bucle hace 2 veces «Adelante, Adelante»: son 4 casillas.' },
      { k: 'predict', ph: 'prova', q: 'I ara? Fixa\'t en el que ve <b>després</b> del bucle.|¿Y ahora? Fíjate en lo que viene <b>después</b> del bucle.',
        w: { map: ['.....', '...B.', '>###C', '...A.'] }, prog: TP('3{ f } r f'), a: 'A', ex: "Primer el bucle (3 caselles) i després, un sol cop, el gir a la dreta i l'Endavant: baixa a la A.|Primero el bucle (3 casillas) y después, una sola vez, el giro a la derecha y el Adelante: baja a la A." },
      { k: 'spot', ph: 'investiga', q: 'Aquest programa hauria de portar en Bit a la bandera, però xoca. Pots executar-lo per veure-ho. <b>Toca el bucle que té el número equivocat.</b>|Este programa debería llevar a Bit a la bandera, pero choca. Puedes ejecutarlo para verlo. <b>Toca el bucle que tiene el número equivocado.</b>',
        w: { map: ['v....', '#....', '#....', '###F.', 'RRRRR'] }, prog: TPX('4!{ f } l 3{ f }'), ex: 'És el primer bucle: en Bit només ha de baixar 3 caselles. Amb 4, xoca amb les roques.|Es el primer bucle: Bit solo tiene que bajar 3 casillas. Con 4, choca con las rocas.' },
      { k: 'move', ph: 'pausa', secs: 25, t: "Fes un bucle amb el cos: <b>Repeteix 4 vegades: salta i aplaudeix</b>. Ara: <b>Repeteix 3 vegades: gira't i toca't el nas</b>. Compta les voltes en veu alta!|Haz un bucle con el cuerpo: <b>Repite 4 veces: salta y aplaude</b>. Ahora: <b>Repite 3 veces: gírate y tócate la nariz</b>. ¡Cuenta las vueltas en voz alta!" },
      { k: 'build', ph: 'repte', q: 'Porta el missatge fins al far amb <b>només 2 blocs</b>. Posa un bucle i, a dins, un Endavant.|Lleva el mensaje hasta el faro con <b>solo 2 bloques</b>. Pon un bucle y, dentro, un Adelante.',
        w: { map: ['.......', '>#####F', '.......'] }, pal: TK_LOOP, sol: TP('6{ f }'), max: 2, hint: 'Compta les caselles fins a la bandera i posa aquest número al bucle (toca el bucle i fes servir − i +).|Cuenta las casillas hasta la bandera y pon ese número en el bucle (toca el bucle y usa − y +).' },
      { k: 'build', ph: 'repte', q: 'Dos trams llargs i un revolt. Fes-ho amb <b>5 blocs</b> com a màxim.|Dos tramos largos y una curva. Hazlo con <b>5 bloques</b> como máximo.',
        w: { map: ['#####F', '#.....', '#.....', '#.....', '^.....'] }, pal: TK_LOOP, sol: TP('4{ f } r 5{ f }'), max: 5, hint: "Un bucle per pujar, un gir i un altre bucle per anar cap a la dreta. Quantes caselles té cada tram?|Un bucle para subir, un giro y otro bucle para ir hacia la derecha. ¿Cuántas casillas tiene cada tramo?" },
      { k: 'build', ph: 'repte', q: 'Aquest programa té un número equivocat i en Bit xoca. <b>Toca el bucle</b> que falla i canvia-li el número amb − i +.|Este programa tiene un número equivocado y Bit choca. <b>Toca el bucle</b> que falla y cámbiale el número con − y +.',
        w: { map: ['>###.', '...#.', '...#.', '.F##.'] }, pal: TK_LOOP, prog: TP('3{ f } r 2{ f } r 2{ f }'), sol: TP('3{ f } r 3{ f } r 2{ f }'), hint: 'Executa-ho pas a pas i mira a quin tram en Bit gira massa aviat. Compta les caselles de baixada.|Ejecútalo paso a paso y mira en qué tramo Bit gira demasiado pronto. Cuenta las casillas de bajada.' },
      { k: 'build', ph: 'repte', q: 'El camí fins al far! Recull les 2 estrelles i arriba a la bandera amb <b>5 blocs</b> com a màxim.|¡El camino hasta el faro! Recoge las 2 estrellas y llega a la bandera con <b>5 bloques</b> como máximo.',
        w: { map: ['......F', '......#', '......*', '......#', '......#', '>##*###'] }, pal: TK_LOOP, sol: TP('6{ f } l 5{ f }'), max: 5, hint: 'Les estrelles són al camí: no cal fer res especial. Compta bé les caselles de cada tram.|Las estrellas están en el camino: no hace falta hacer nada especial. Cuenta bien las casillas de cada tramo.' },
      { k: 'create', ph: 'crea', name: 'El camí del far|El camino del faro', q: 'Ara decideixes tu! Porta en Bit a la bandera <b>recollint les 3 estrelles</b>. Condició: fes servir <b>almenys 2 bucles</b>.|¡Ahora decides tú! Lleva a Bit a la bandera <b>recogiendo las 3 estrellas</b>. Condición: usa <b>al menos 2 bucles</b>.',
        crit: ['Recull les 3 estrelles|Recoge las 3 estrellas', 'Acaba a la bandera|Termina en la bandera', 'Fa servir almenys 2 bucles|Usa al menos 2 bucles'],
        check: p => bitCountK(p, ['rep']) >= 2 ? null : 'Funciona, però hi ha menys de 2 bucles. On hi ha blocs iguals seguits?|Funciona, pero hay menos de 2 bucles. ¿Dónde hay bloques iguales seguidos?',
        w: { map: ['...*.F', '.R....', '...*..', '.R...R', '......', '>.*...'] }, pal: TK_LOOP, sol: TP('3{ f } l 5{ f } r 2{ f }') },
      { k: 'quiz', ph: 'tanca', q: 'Què fa el bloc <b>Repeteix 4 vegades</b>?|¿Qué hace el bloque <b>Repite 4 veces</b>?',
        opts: ['Fa 4 vegades els blocs que té a dins|Hace 4 veces los bloques que tiene dentro', 'Fa avançar en Bit 4 caselles, sempre|Hace avanzar a Bit 4 casillas, siempre', 'Repeteix tot el programa des del principi|Repite todo el programa desde el principio'], a: 0 },
      { k: 'quiz', ph: 'tanca', w: { map: ['.......', '>#####F', '.......'] }, q: 'Amb el bucle <b>Repeteix N vegades: Endavant</b>, quin número porta en Bit a la bandera?|Con el bucle <b>Repite N veces: Adelante</b>, ¿qué número lleva a Bit a la bandera?',
        opts: ['6', '7', '5'], a: 0, ex: 'Hi ha 6 salts de casella fins a la bandera.|Hay 6 saltos de casilla hasta la bandera.' },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 2 · Troba el patró ---------- */
  { id: 'r2-2', t: 'Troba el patró|Encuentra el patrón', min: 35, badge: 'patro',
    learn: ['Un <b>patró</b> és un tros que es repeteix sempre igual.|Un <b>patrón</b> es un trozo que se repite siempre igual.',
      'Per fer el bucle, troba el tros que es repeteix i compta quantes vegades hi surt.|Para hacer el bucle, encuentra el trozo que se repite y cuenta cuántas veces sale.',
      "Dins d'un bucle hi poden anar molts blocs: a cada volta es fan tots, en ordre.|Dentro de un bucle pueden ir muchos bloques: en cada vuelta se hacen todos, en orden."],
    steps: [
      { k: 'quiz', ph: 'recorda', w: { map: ['.....', '>###F'] }, q: 'Recordes el bucle? Quin porta en Bit a la bandera?|¿Recuerdas el bucle? ¿Cuál lleva a Bit a la bandera?',
        opts: ['Repeteix 4 vegades: Endavant|Repite 4 veces: Adelante', 'Repeteix 5 vegades: Endavant|Repite 5 veces: Adelante', 'Repeteix 3 vegades: Endavant|Repite 3 veces: Adelante'], a: 0, ex: '4 salts de casella: 4 voltes del bucle.|4 saltos de casilla: 4 vueltas del bucle.' },
      { k: 'story', ph: 'missio', who: 'both', scene: 'poble', title: 'El jardí del poble|El jardín del pueblo', t: 'Al poble preparen la festa major i els jardiners han plantat flors per tot arreu: vermella, groga, vermella, groga… En Bit les ha de regar, i descobrirà que els camins del jardí també tenen un secret: <b>es repeteixen</b>!|En el pueblo preparan la fiesta mayor y los jardineros han plantado flores por todas partes: roja, amarilla, roja, amarilla… Bit tiene que regarlas, ¡y descubrirá que los caminos del jardín también tienen un secreto: <b>se repiten</b>!' },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'think', w: { map: ['>#..', '.##.', '..##', '...F'] },
        t: 'BIP! Aquest camí fa esglaons: endavant, gira, endavant, gira… <b>Sempre el mateix tros!</b> Si trobo el tros que es repeteix, el puc posar dins d\'un bucle.|¡BIP! Este camino hace escalones: adelante, gira, adelante, gira… <b>¡Siempre el mismo trozo!</b> Si encuentro el trozo que se repite, lo puedo poner dentro de un bucle.' },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Patró|Patrón', t: 'Què és un patró?|¿Qué es un patrón?', anim: 'u2pattern',
          x: "Un <span class='hl'>patró</span> és un tros que es repeteix sempre igual, en el mateix ordre. Hi ha patrons a les rajoles del terra, a les ratlles d'una samarreta o a la tornada d'una cançó. Si trobes el patró, saps què ve després.|Un <span class='hl'>patrón</span> es un trozo que se repite siempre igual, en el mismo orden. Hay patrones en las baldosas del suelo, en las rayas de una camiseta o en el estribillo de una canción. Si encuentras el patrón, sabes qué viene después." },
        { k: 'El tros|El trozo', t: 'Troba el tros que es repeteix|Encuentra el trozo que se repite', anim: 'u2stairs',
          x: 'Mira el programa i busca el grup de blocs que surt diverses vegades seguides. Aquest grup va <b>dins</b> del bucle, i el número del bucle és <b>quantes vegades</b> hi surt.|Mira el programa y busca el grupo de bloques que sale varias veces seguidas. Ese grupo va <b>dentro</b> del bucle, y el número del bucle es <b>cuántas veces</b> sale.' },
        { k: 'Molts blocs a dins|Muchos bloques dentro', t: 'Un quadrat amb un bucle|Un cuadrado con un bucle', demo: { w: { map: ['>##', '#.#', '###'] }, prog: TP('4{ f f r }') },
          x: "Dins d'un bucle hi poden anar molts blocs. A cada volta, en Bit els fa <b>tots, en ordre</b>: endavant, endavant, gira. Quatre voltes… i ha fet la volta sencera al parterre!|Dentro de un bucle pueden ir muchos bloques. En cada vuelta, Bit los hace <b>todos, en orden</b>: adelante, adelante, gira. Cuatro vueltas… ¡y ha dado la vuelta entera al parterre!" },
        { k: 'Escales|Escaleras', t: 'Escales i ziga-zagues|Escaleras y zigzags', demo: { w: { map: ['>#..', '.##.', '..##', '...F'] }, prog: TP('3{ f r f l }') },
          x: "Un esglaó són 4 blocs: endavant, gira a la dreta, endavant, gira a l'esquerra. Els dos girs es compensen: després de cada esglaó, en Bit torna a mirar cap al mateix costat, i el tros es pot repetir.|Un escalón son 4 bloques: adelante, gira a la derecha, adelante, gira a la izquierda. Los dos giros se compensan: después de cada escalón, Bit vuelve a mirar hacia el mismo lado, y el trozo se puede repetir." },
        { k: 'Compte!|¡Cuidado!', t: 'Posa-hi el tros sencer|Pon el trozo entero', demo: { w: { map: ['>#..', '.##.', '..##', '...F'] }, prog: TP('3{ f r }'), speed: 950 },
          x: "Aquí al bucle li falta un tros: endavant, gira a la dreta… i prou. A la segona volta, en Bit ja no mira cap on toca i xoca. Abans de posar un tros dins d'un bucle, comprova que en acabar-lo en Bit <b>mira com al principi</b>.|Aquí al bucle le falta un trozo: adelante, gira a la derecha… y ya está. En la segunda vuelta, Bit ya no mira hacia donde toca y choca. Antes de poner un trozo dentro de un bucle, comprueba que al terminarlo Bit <b>mira como al principio</b>.",
          bad: 'Posar dins del bucle només una part del tros.|Poner dentro del bucle solo una parte del trozo.', good: 'Posar-hi el tros sencer, amb els dos girs.|Poner el trozo entero, con los dos giros.' }
      ] },
      { k: 'quiz', ph: 'mans', q: 'Al jardí hi ha flors en fila: 🌷🌼🌼🌷🌼🌼🌷🌼… <b>Quina flor va ara?</b>|En el jardín hay flores en fila: 🌷🌼🌼🌷🌼🌼🌷🌼… <b>¿Qué flor va ahora?</b>',
        opts: ['🌼 Una margarida|🌼 Una margarita', '🌷 Una tulipa|🌷 Un tulipán', '🌻 Un gira-sol|🌻 Un girasol'], a: 0, ex: 'El patró és 🌷🌼🌼: una tulipa i dues margarides. Després de 🌷🌼 toca una altra 🌼.|El patrón es 🌷🌼🌼: un tulipán y dos margaritas. Después de 🌷🌼 toca otra 🌼.' },
      { k: 'quiz', ph: 'mans', q: "Aquest programa fa una escala: <b>Endavant, Gira a la dreta, Endavant, Gira a l'esquerra, Endavant, Gira a la dreta, Endavant, Gira a l'esquerra</b>. Quin és el bucle bo?|Este programa hace una escalera: <b>Adelante, Gira a la derecha, Adelante, Gira a la izquierda, Adelante, Gira a la derecha, Adelante, Gira a la izquierda</b>. ¿Cuál es el bucle bueno?",
        opts: ["Repeteix 2 vegades: Endavant, Gira a la dreta, Endavant, Gira a l'esquerra|Repite 2 veces: Adelante, Gira a la derecha, Adelante, Gira a la izquierda", 'Repeteix 4 vegades: Endavant, Gira a la dreta|Repite 4 veces: Adelante, Gira a la derecha', 'Repeteix 4 vegades: Endavant|Repite 4 veces: Adelante'], a: 0,
        ex: "El tros sencer té 4 blocs i surt 2 vegades. «Endavant, Gira a la dreta» no es repeteix sempre igual: un cop ve un gir a l'esquerra.|El trozo entero tiene 4 bloques y sale 2 veces. «Adelante, Gira a la derecha» no se repite siempre igual: una vez viene un giro a la izquierda." },
      { k: 'unplug', ph: 'mans', ico: '🔍', title: 'Caçadors de patrons|Cazadores de patrones', t: 'Amb algú de casa, sortiu a buscar patrons:|Con alguien de casa, salid a buscar patrones:',
        steps: ['Busqueu 3 patrons per casa: les rajoles, una cortina, una samarreta de ratlles, una tanca…|Buscad 3 patrones por casa: las baldosas, una cortina, una camiseta de rayas, una valla…',
          'Per a cada patró, digueu en veu alta quin és el tros que es repeteix i quantes vegades hi surt.|Para cada patrón, decid en voz alta cuál es el trozo que se repite y cuántas veces sale.',
          'Ara feu-ne un vosaltres amb objectes (culleres, peces de construcció, llapis de colors) i deixeu-lo a mitges.|Ahora haced uno vosotros con objetos (cucharas, piezas de construcción, lápices de colores) y dejadlo a medias.',
          "L'altra persona l'ha de continuar: quina peça va ara? Canvieu els papers.|La otra persona tiene que continuarlo: ¿qué pieza va ahora? Cambiad los papeles."],
        tip: "Un patró ha de ser sempre igual. Si una peça canvia, ja no és el mateix patró!|Un patrón tiene que ser siempre igual. ¡Si una pieza cambia, ya no es el mismo patrón!" },
      { k: 'predict', ph: 'prova', q: 'En Bit fa la volta al parterre. <b>On acabarà?</b>|Bit da la vuelta al parterre. <b>¿Dónde terminará?</b>',
        w: { map: ['>#C', '#.#', 'B#A'] }, prog: TP('2{ f f r }'), a: 'A', ex: 'Cada volta fa dos passos i un gir. Amb 2 voltes, en Bit dobla dues cantonades i acaba a la A.|Cada vuelta hace dos pasos y un giro. Con 2 vueltas, Bit dobla dos esquinas y termina en la A.' },
      { k: 'predict', ph: 'prova', q: 'Una ziga-zaga cap amunt. <b>On acabarà?</b>|Un zigzag hacia arriba. <b>¿Dónde terminará?</b>',
        w: { map: ['...B', '..A#', '.##.', '>#.C'] }, prog: TP('2{ f l f r }'), a: 'A', ex: "Cada volta puja un esglaó: una casella a la dreta i una amunt. Amb 2 voltes, puja 2 esglaons.|Cada vuelta sube un escalón: una casilla a la derecha y una arriba. Con 2 vueltas, sube 2 escalones." },
      { k: 'spot', ph: 'investiga', q: "Aquest programa hauria de baixar l'escala, però en Bit xoca. Pots executar-lo. <b>Toca el gir equivocat.</b>|Este programa debería bajar la escalera, pero Bit choca. Puedes ejecutarlo. <b>Toca el giro equivocado.</b>",
        w: { map: ['>#..', '.##.', '..##', '...F'] }, prog: TPX('3{ f r f r! }'), ex: "És l'últim gir: amb dos girs a la dreta, en Bit queda mirant enrere. Havia de girar a l'esquerra per tornar a mirar com al principi.|Es el último giro: con dos giros a la derecha, Bit queda mirando hacia atrás. Tenía que girar a la izquierda para volver a mirar como al principio." },
      { k: 'move', ph: 'pausa', secs: 25, t: "Fes el patró de l'escala amb el cos: <b>un pas endavant, gira a la dreta, un pas endavant, gira a l'esquerra</b>. Repeteix-lo 4 vegades. Mira cap on mires al final!|Haz el patrón de la escalera con el cuerpo: <b>un paso adelante, gira a la derecha, un paso adelante, gira a la izquierda</b>. Repítelo 4 veces. ¡Mira hacia dónde miras al final!" },
      { k: 'parsons', ph: 'repte', q: 'Els blocs estan barrejats. <b>Posa\'ls en ordre</b> perquè en Bit arribi a la bandera (els bucles ja porten els blocs a dins).|Los bloques están mezclados. <b>Ponlos en orden</b> para que Bit llegue a la bandera (los bucles ya llevan los bloques dentro).',
        w: { map: ['>##..', '..#..', '..#..', '..##F'] }, pool: TP('2{ f } r 3{ f } l 2{ f }'), sol: TP('2{ f } r 3{ f } l 2{ f }'), hint: 'Primer un tram curt cap a la dreta, després baixa. Quin bucle té el número de la baixada?|Primero un tramo corto hacia la derecha, después baja. ¿Qué bucle tiene el número de la bajada?' },
      { k: 'build', ph: 'repte', q: 'Rega les 4 flors del parterre (les estrelles) fent-ne la volta sencera. Màxim <b>5 blocs</b>.|Riega las 4 flores del parterre (las estrellas) dándole la vuelta entera. Máximo <b>5 bloques</b>.',
        w: { map: ['>#*#', '*..#', '#..*', '#*##'] }, pal: TK_LOOP, sol: TP('4{ f f f r }'), max: 5, hint: 'Cada costat és igual: quants Endavant té un costat? Després del costat, un gir. Repeteix-ho per cada costat.|Cada lado es igual: ¿cuántos Adelante tiene un lado? Después del lado, un giro. Repítelo para cada lado.' },
      { k: 'build', ph: 'repte', q: "En aquest bucle falta un bloc i en Bit xoca. <b>Troba'l i afegeix-lo</b> dins del bucle.|En este bucle falta un bloque y Bit choca. <b>Encuéntralo y añádelo</b> dentro del bucle.",
        w: { map: ['>*...', '.#*..', '..#*.', '...#*', '....F'] }, pal: TK_LOOP, prog: TP('4{ f r f }'), sol: TP('4{ f r f l }'), hint: "Després de cada esglaó, en Bit ha de tornar a mirar cap a la dreta. Quin gir li falta al final del tros?|Después de cada escalón, Bit tiene que volver a mirar hacia la derecha. ¿Qué giro le falta al final del trozo?" },
      { k: 'build', ph: 'repte', q: 'Una pujada amb estrelles! Troba el patró, recull les 3 estrelles i arriba a la bandera. Màxim <b>6 blocs</b>.|¡Una subida con estrellas! Encuentra el patrón, recoge las 3 estrellas y llega a la bandera. Máximo <b>6 bloques</b>.',
        w: { map: ['....#*F', '..#*#..', '#*#....', '^......'] }, pal: TK_LOOP, sol: TP('3{ f r f f l }'), max: 6, hint: "Mira un esglaó: quantes caselles puja i quantes va cap a la dreta? Aquest és el tros del bucle.|Mira un escalón: ¿cuántas casillas sube y cuántas va hacia la derecha? Ese es el trozo del bucle." },
      { k: 'create', ph: 'crea', name: 'El meu patró|Mi patrón', q: 'Inventa un patró per recollir les 4 estrelles i arribar a la bandera. Condició: un bucle amb <b>almenys 3 blocs a dins</b>.|Inventa un patrón para recoger las 4 estrellas y llegar a la bandera. Condición: un bucle con <b>al menos 3 bloques dentro</b>.',
        crit: ['Recull les 4 estrelles|Recoge las 4 estrellas', 'Acaba a la bandera|Termina en la bandera', 'Un bucle amb almenys 3 blocs a dins|Un bucle con al menos 3 bloques dentro'],
        check: p => p.some(b => b.k === 'rep' && (b.b || []).length >= 3) ? null : 'Funciona! Però el repte demana un bucle amb almenys 3 blocs a dins. Busca el patró de l\'escala.|¡Funciona! Pero el reto pide un bucle con al menos 3 bloques dentro. Busca el patrón de la escalera.',
        w: { map: ['.....F', '.R..*.', '...*..', '..*..R', '.*....', '>...R.'] }, pal: TK_LOOP, sol: TP('5{ f l f r }') },
      { k: 'quiz', ph: 'tanca', q: 'Per acabar: què és un <b>patró</b>?|Para terminar: ¿qué es un <b>patrón</b>?',
        opts: ['Un tros que es repeteix sempre igual|Un trozo que se repite siempre igual', 'Un bloc que fa girar en Bit|Un bloque que hace girar a Bit', 'Un error del programa|Un error del programa'], a: 0 },
      { k: 'quiz', ph: 'tanca', q: 'Quin bucle fa que en Bit doni la volta a un quadrat?|¿Qué bucle hace que Bit dé la vuelta a un cuadrado?',
        opts: ['Repeteix 4 vegades: Endavant, Endavant, Gira a la dreta|Repite 4 veces: Adelante, Adelante, Gira a la derecha', 'Repeteix 4 vegades: Endavant|Repite 4 veces: Adelante', 'Repeteix 2 vegades: Gira a la dreta|Repite 2 veces: Gira a la derecha'], a: 0,
        ex: 'Un quadrat té 4 costats iguals: cada volta fa un costat i un gir.|Un cuadrado tiene 4 lados iguales: cada vuelta hace un lado y un giro.' },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 3 · El llapis d'en Bit ---------- */
  { id: 'r2-3', t: "El llapis d'en Bit|El lápiz de Bit", min: 35,
    learn: ['Amb el llapis, en Bit pinta cada casella on entra.|Con el lápiz, Bit pinta cada casilla a la que entra.',
      'El bloc «Pinta de» pinta la casella on és en Bit, del color que triïs.|El bloque «Pinta de» pinta la casilla donde está Bit, del color que elijas.',
      'Amb un bucle i el llapis, en Bit dibuixa línies, quadrats i escales.|Con un bucle y el lápiz, Bit dibuja líneas, cuadrados y escaleras.'],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'Quin és el tros que es repeteix? <b>Endavant, Endavant, Gira a la dreta, Endavant, Endavant, Gira a la dreta, Endavant, Endavant, Gira a la dreta</b>|¿Cuál es el trozo que se repite? <b>Adelante, Adelante, Gira a la derecha, Adelante, Adelante, Gira a la derecha, Adelante, Adelante, Gira a la derecha</b>',
        opts: ['Endavant, Endavant, Gira a la dreta (3 vegades)|Adelante, Adelante, Gira a la derecha (3 veces)', 'Endavant, Gira a la dreta (3 vegades)|Adelante, Gira a la derecha (3 veces)', 'Endavant (6 vegades)|Adelante (6 veces)'], a: 0 },
      { k: 'story', ph: 'missio', who: 'both', scene: 'taller', title: 'Un regal per a en Bit|Un regalo para Bit', t: "Al taller, en Numi ha preparat un regal per a en Bit: un <b>llapis</b> que s'enganxa a sota del seu cos! Per a la festa major, en Bit pintarà dibuixos al terra de la plaça.|En el taller, Numi ha preparado un regalo para Bit: ¡un <b>lápiz</b> que se engancha debajo de su cuerpo! Para la fiesta mayor, Bit pintará dibujos en el suelo de la plaza." },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'happy', w: { map: ['>...', '....'], target: ['.ppp', '....'] }, t: 'BIP BIP! Un llapis! Abans de començar, aprèn les regles del meu llapis:|¡BIP BIP! ¡Un lápiz! Antes de empezar, aprende las reglas de mi lápiz:',
        box: '<ol><li>Quan porto el llapis, pinto cada casella <b>on entro</b>.</li><li>La casella on començo no es pinta.</li><li>Els girs no pinten: no em moc de casella.</li><li>Els requadres de punts són el dibuix que cal fer: <b>ni una casella més</b>.</li></ol>|<ol><li>Cuando llevo el lápiz, pinto cada casilla <b>a la que entro</b>.</li><li>La casilla donde empiezo no se pinta.</li><li>Los giros no pintan: no me muevo de casilla.</li><li>Los recuadros de puntos son el dibujo que hay que hacer: <b>ni una casilla más</b>.</li></ol>' },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Llapis|Lápiz', t: 'Dibuixar caminant|Dibujar caminando', anim: 'u2pen',
          x: "Quan un repte té el <span class='hl'>llapis</span> posat, cada <b>Endavant</b> deixa pintada la casella on entra en Bit. La casella de sortida no es pinta, i els girs tampoc: en Bit no canvia de casella.|Cuando un reto tiene el <span class='hl'>lápiz</span> puesto, cada <b>Adelante</b> deja pintada la casilla a la que entra Bit. La casilla de salida no se pinta, y los giros tampoco: Bit no cambia de casilla." },
        { k: 'Línia|Línea', t: 'Una línia amb un bucle|Una línea con un bucle', demo: { w: { map: ['>....', '.....'], pen: true, target: ['.pppp', '.....'] }, prog: TP('4{ f }') },
          x: "Els requadres de punts són el dibuix que demana el repte. Per fer una línia de 4 caselles, n'hi ha prou amb un bucle de 4 Endavant.|Los recuadros de puntos son el dibujo que pide el reto. Para hacer una línea de 4 casillas, basta con un bucle de 4 Adelante." },
        { k: 'Quadrat|Cuadrado', t: 'Un quadrat de llapis|Un cuadrado de lápiz', demo: { w: { map: ['>..', '...', '...'], pen: true, target: ['ppp', 'p.p', 'ppp'] }, prog: TP('4{ f f r }') },
          x: "El patró del quadrat de la sessió anterior ara deixa un dibuix! A l'última volta, en Bit torna a entrar a la casella de sortida, i llavors sí que la pinta.|¡El patrón del cuadrado de la sesión anterior ahora deja un dibujo! En la última vuelta, Bit vuelve a entrar en la casilla de salida, y entonces sí que la pinta." },
        { k: 'Pinta de|Pinta de', t: 'El bloc «Pinta de»|El bloque «Pinta de»', demo: { w: { map: ['>....', '.....'], target: ['.ryry', '.....'] }, prog: TP('2{ f paint:r f paint:y }') },
          x: "El bloc <b>Pinta de</b> pinta la casella on és en Bit, del color que triïs: toca el bloc i després «Canvia el color». Pinta no mou en Bit: abans cal un <b>Endavant</b> per entrar a la casella. I amb un bucle… un patró de colors!|El bloque <b>Pinta de</b> pinta la casilla donde está Bit, del color que elijas: toca el bloque y después «Cambia el color». Pinta no mueve a Bit: antes hace falta un <b>Adelante</b> para entrar en la casilla. Y con un bucle… ¡un patrón de colores!" },
        { k: 'Compte!|¡Cuidado!', t: 'Pinta no camina|Pinta no camina', anim: 'u2paint',
          x: 'Si poses <b>Pinta</b> tres vegades seguides, en Bit es queda quiet i pinta la mateixa casella tres vegades. Per pintar una fila, alterna: <b>Endavant, Pinta, Endavant, Pinta…</b>|Si pones <b>Pinta</b> tres veces seguidas, Bit se queda quieto y pinta la misma casilla tres veces. Para pintar una fila, alterna: <b>Adelante, Pinta, Adelante, Pinta…</b>',
          bad: 'Pinta, Pinta, Pinta: en Bit no es mou.|Pinta, Pinta, Pinta: Bit no se mueve.', good: 'Endavant, Pinta: entra a la casella i la pinta.|Adelante, Pinta: entra en la casilla y la pinta.' }
      ] },
      { k: 'quiz', ph: 'mans', q: 'En Bit porta el llapis i fa: <b>Endavant, Endavant, Gira a la dreta, Endavant</b>. Quantes caselles pinta?|Bit lleva el lápiz y hace: <b>Adelante, Adelante, Gira a la derecha, Adelante</b>. ¿Cuántas casillas pinta?',
        opts: ['3', '4', '2'], a: 0, ex: 'Només pinten els Endavant: 3. El gir i la casella de sortida no pinten.|Solo pintan los Adelante: 3. El giro y la casilla de salida no pintan.' },
      { k: 'unplug', ph: 'mans', ico: '✏️', title: 'Robot dibuixant|Robot dibujante', t: "Necessiteu un full de quadrícula i un llapis. Una persona és la programadora i l'altra, el robot que dibuixa.|Necesitáis una hoja de cuadrícula y un lápiz. Una persona es la programadora y la otra, el robot que dibuja.",
        steps: ['Marqueu la casella de sortida amb un punt i una fletxa cap on mira el robot.|Marcad la casilla de salida con un punto y una flecha hacia donde mira el robot.',
          'La programadora diu un bucle, per exemple: «<b>Repeteix 4 vegades</b>: endavant, endavant, gira a la dreta».|La programadora dice un bucle, por ejemplo: «<b>Repite 4 veces</b>: adelante, adelante, gira a la derecha».',
          'El robot pinta cada casella on entra, i només aquestes.|El robot pinta cada casilla a la que entra, y solo esas.',
          'Quin dibuix ha sortit? Canvieu els papers i inventeu-ne un altre: una L, una escala…|¿Qué dibujo ha salido? Cambiad los papeles e inventad otro: una L, una escalera…'] },
      { k: 'predict', ph: 'prova', q: 'En Bit porta el llapis. Quan acabi el dibuix, <b>on serà?</b>|Bit lleva el lápiz. Cuando termine el dibujo, <b>¿dónde estará?</b>',
        w: { map: ['A..B', '....', '....', '^..C'], pen: true }, prog: TP('3{ f } r 3{ f }'), a: 'B', ex: 'Puja 3 caselles fins a la A, gira a la dreta i en fa 3 més: acaba a la B.|Sube 3 casillas hasta la A, gira a la derecha y hace 3 más: termina en la B.' },
      { k: 'spot', ph: 'investiga', q: 'En Bit havia de dibuixar un quadrat, però surt del mapa. Executa-ho i <b>toca el bloc equivocat</b>.|Bit tenía que dibujar un cuadrado, pero se sale del mapa. Ejecútalo y <b>toca el bloque equivocado</b>.',
        w: { map: ['>..', '...', '...'], pen: true, target: ['ppp', 'p.p', 'ppp'] }, prog: TPX('4{ f f l! }'), ex: "És el gir: amb l'esquerra, en Bit mira amunt i surt del mapa. Per baixar havia de girar a la dreta.|Es el giro: con la izquierda, Bit mira arriba y se sale del mapa. Para bajar tenía que girar a la derecha." },
      { k: 'move', ph: 'pausa', secs: 25, t: 'Dibuixa a l\'aire amb el dit: <b>un quadrat gegant</b> (4 costats i 4 girs). Ara una escala de 3 esglaons. I ara, el quadrat amb el peu!|Dibuja en el aire con el dedo: <b>un cuadrado gigante</b> (4 lados y 4 giros). Ahora una escalera de 3 escalones. ¡Y ahora, el cuadrado con el pie!' },
      { k: 'build', ph: 'repte', q: 'Pinta la tanca del jardí: una línia de 5 caselles. Màxim <b>2 blocs</b>.|Pinta la valla del jardín: una línea de 5 casillas. Máximo <b>2 bloques</b>.',
        w: { map: ['>.....', '......'], pen: true, target: ['.ppppp', '......'] }, pal: TK_LOOP, sol: TP('5{ f }'), max: 2, hint: 'Compta els requadres de punts: tants Endavant com requadres.|Cuenta los recuadros de puntos: tantos Adelante como recuadros.' },
      { k: 'build', ph: 'repte', q: 'Dibuixa una <b>L</b> gegant. En Bit comença mirant avall. Màxim <b>5 blocs</b>.|Dibuja una <b>L</b> gigante. Bit empieza mirando abajo. Máximo <b>5 bloques</b>.',
        w: { map: ['v...', '....', '....', '....'], pen: true, target: ['....', 'p...', 'p...', 'pppp'] }, pal: TK_LOOP, sol: TP('3{ f } l 3{ f }'), max: 5, hint: "Un bucle per baixar i un altre per anar cap a la dreta. En Bit mira avall: cap a quin costat ha de girar?|Un bucle para bajar y otro para ir hacia la derecha. Bit mira abajo: ¿hacia qué lado tiene que girar?" },
      { k: 'build', ph: 'repte', q: "Dibuixa el marc d'un quadre: un quadrat de 4 × 4. Màxim <b>5 blocs</b>.|Dibuja el marco de un cuadro: un cuadrado de 4 × 4. Máximo <b>5 bloques</b>.",
        w: { map: ['>...', '....', '....', '....'], pen: true, target: ['pppp', 'p..p', 'p..p', 'pppp'] }, pal: TK_LOOP, sol: TP('4{ f f f r }'), max: 5, hint: 'Com el quadrat de la teoria, però cada costat és més llarg. Quants Endavant té cada costat?|Como el cuadrado de la teoría, pero cada lado es más largo. ¿Cuántos Adelante tiene cada lado?' },
      { k: 'build', ph: 'repte', q: 'Dibuixa una escala de 3 esglaons. En Bit comença mirant amunt. Màxim <b>5 blocs</b>.|Dibuja una escalera de 3 escalones. Bit empieza mirando arriba. Máximo <b>5 bloques</b>.',
        w: { map: ['....', '....', '....', '^...'], pen: true, target: ['..pp', '.pp.', 'pp..', '....'] }, pal: TK_LOOP, sol: TP('3{ f r f l }'), max: 5, hint: "Un esglaó: amunt, gira a la dreta, una a la dreta, i torna a mirar amunt.|Un escalón: arriba, gira a la derecha, una a la derecha, y vuelve a mirar arriba." },
      { k: 'build', ph: 'repte', q: "Pinta la bandera de la festa: <b>vermell, groc, vermell, groc</b>. Toca el bloc Pinta per canviar-ne el color. Màxim <b>5 blocs</b>.|Pinta la bandera de la fiesta: <b>rojo, amarillo, rojo, amarillo</b>. Toca el bloque Pinta para cambiar su color. Máximo <b>5 bloques</b>.",
        w: { map: ['>....', '.....'], target: ['.ryry', '.....'] }, pal: ['fwd', 'left', 'right', 'rep', 'paint'], colors: ['r', 'y'], sol: TP('2{ f paint:r f paint:y }'), max: 5, hint: 'El patró de colors és «vermell, groc». Cada color necessita un Endavant i un Pinta.|El patrón de colores es «rojo, amarillo». Cada color necesita un Adelante y un Pinta.' },
      { k: 'create', ph: 'crea', name: 'El meu dibuix de llapis|Mi dibujo de lápiz', q: 'Dibuixa el que vulguis amb el llapis: una lletra, una escala, una casa… Ha de tenir <b>almenys 8 caselles pintades</b> i un bucle.|Dibuja lo que quieras con el lápiz: una letra, una escalera, una casa… Tiene que tener <b>al menos 8 casillas pintadas</b> y un bucle.',
        crit: ['Fa servir almenys un bucle|Usa al menos un bucle', 'Pinta almenys 8 caselles|Pinta al menos 8 casillas', 'En Bit no surt del mapa|Bit no se sale del mapa'],
        check: p => { if (!bitCountK(p, ['rep'])) return 'Molt bon dibuix! Ara fes-lo amb almenys un bucle.|¡Muy buen dibujo! Ahora hazlo con al menos un bucle.';
          const S = bitFinal({ map: ['......', '......', '......', '......', '......', '^.....'], pen: true }, p).S;
          return Object.keys(S.paint).length >= 8 ? null : 'El dibuix és massa petit: pinta almenys 8 caselles.|El dibujo es demasiado pequeño: pinta al menos 8 casillas.'; },
        w: { map: ['......', '......', '......', '......', '......', '^.....'], pen: true }, pal: TK_LOOP, sol: TP('4{ f f f r }') },
      { k: 'quiz', ph: 'tanca', q: 'Amb el llapis posat, quina casella <b>no</b> es pinta?|Con el lápiz puesto, ¿qué casilla <b>no</b> se pinta?',
        opts: ['La casella on comença en Bit|La casilla donde empieza Bit', 'Les caselles on entra en Bit|Las casillas a las que entra Bit', "L'última casella del camí|La última casilla del camino"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: "Quin bloc pinta la casella on és en Bit, sense moure'l?|¿Qué bloque pinta la casilla donde está Bit, sin moverlo?", opts: [tChip('paint'), tChip('fwd'), tChip('rep')], a: 0,
        ex: 'Pinta no mou en Bit. Per pintar la casella del costat, primer cal un Endavant.|Pinta no mueve a Bit. Para pintar la casilla de al lado, primero hace falta un Adelante.' },
      { k: 'feel', ph: 'tanca' }
    ] },

  /* ---------- Sessió 4 · Projecte: el mosaic de l'illa ---------- */
  { id: 'r2-4', t: "Projecte: el mosaic de l'illa|Proyecto: el mosaico de la isla", min: 40, proj: true, badge: 'mosaic',
    learn: ['Un mosaic es programa fila a fila: cada fila, un bucle.|Un mosaico se programa fila a fila: cada fila, un bucle.',
      'Les files iguals es repeteixen amb un bucle gran, i a dins hi pot haver altres bucles.|Las filas iguales se repiten con un bucle grande, y dentro puede haber otros bucles.',
      'Has creat el teu propi mosaic amb bucles!|¡Has creado tu propio mosaico con bucles!'],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'Recordes el bloc Pinta? Quin programa pinta 3 caselles seguides de vermell?|¿Recuerdas el bloque Pinta? ¿Qué programa pinta 3 casillas seguidas de rojo?',
        opts: ['Repeteix 3 vegades: Endavant, Pinta de vermell|Repite 3 veces: Adelante, Pinta de rojo', 'Repeteix 3 vegades: Pinta de vermell|Repite 3 veces: Pinta de rojo', 'Endavant, Pinta de vermell|Adelante, Pinta de rojo'], a: 0,
        ex: "Sense l'Endavant, en Bit pintaria 3 vegades la mateixa casella.|Sin el Adelante, Bit pintaría 3 veces la misma casilla." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'poble', title: 'La festa major|La fiesta mayor', t: 'Ja arriba la festa major! La gent del poble vol un <b>mosaic</b> de rajoles de colors al terra de la plaça, i en Bit l\'ha de pintar. Avui faràs el projecte de la unitat: planificar un mosaic, programar-lo amb bucles i crear-ne un de teu.|¡Ya llega la fiesta mayor! La gente del pueblo quiere un <b>mosaico</b> de baldosas de colores en el suelo de la plaza, y Bit lo tiene que pintar. Hoy harás el proyecto de la unidad: planificar un mosaico, programarlo con bucles y crear uno tuyo.' },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'think', w: { map: ['>.....', '......', '......', '......', '......'], target: ['.rrrr.', '.yyyy.', '.rrrr.', '.yyyy.', '......'] },
        t: 'BIP! Aquest és el mosaic que vol la plaça: 16 rajoles! Si poso un bloc per a cada cosa, faré un programa llarguíssim. Com el puc fer més curt?|¡BIP! Este es el mosaico que quiere la plaza: ¡16 baldosas! Si pongo un bloque para cada cosa, haré un programa larguísimo. ¿Cómo lo puedo hacer más corto?' },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Mosaic|Mosaico', t: 'Un mosaic, fila a fila|Un mosaico, fila a fila', anim: 'u2rows',
          x: "Un <span class='hl'>mosaic</span> és un dibuix fet amb rajoles de colors. Per programar-lo, el <b>descomponem en files</b>, com a la unitat 1. Després busquem les files que són iguals: cada fila igual es pot fer amb el mateix tros de programa.|Un <span class='hl'>mosaico</span> es un dibujo hecho con baldosas de colores. Para programarlo, lo <b>descomponemos en filas</b>, como en la unidad 1. Después buscamos las filas que son iguales: cada fila igual se puede hacer con el mismo trozo de programa." },
        { k: 'Una fila|Una fila', t: 'Una fila amb un bucle|Una fila con un bucle', demo: { w: { map: ['>.....', '......'], target: ['.gggg.', '......'] }, prog: TP('4{ f paint:g }') },
          x: 'En Bit comença <b>fora del mosaic</b>, a la vora. A cada volta del bucle fa <b>Endavant</b> (entra a la rajola) i <b>Pinta</b>. 4 voltes, 4 rajoles.|Bit empieza <b>fuera del mosaico</b>, en el borde. En cada vuelta del bucle hace <b>Adelante</b> (entra en la baldosa) y <b>Pinta</b>. 4 vueltas, 4 baldosas.' },
        { k: 'Mitja volta|Media vuelta', t: 'Canviar de fila|Cambiar de fila', demo: { w: { map: ['>.....', '......'], target: ['.yyyy.', '.uuuu.'] }, prog: TP('4{ f paint:y } 2{ f r } 4{ f paint:u }') },
          x: "Al final de la fila, en Bit surt a la vora i fa <b>Endavant, Gira a la dreta</b> dues vegades: baixa a la fila de sota i queda mirant cap a l'altre costat. La mitja volta també és un patró!|Al final de la fila, Bit sale al borde y hace <b>Adelante, Gira a la derecha</b> dos veces: baja a la fila de abajo y queda mirando hacia el otro lado. ¡La media vuelta también es un patrón!" },
        { k: 'Files iguals|Filas iguales', t: 'Un bucle per a les files iguals|Un bucle para las filas iguales', demo: { w: { map: ['>.....', '......', '......', '......', '......'], target: ['.rrrr.', '.yyyy.', '.rrrr.', '.yyyy.', '......'] }, prog: TP('2{ 4{ f paint:r } 2{ f r } 4{ f paint:y } 2{ f l } }'), speed: 520 },
          x: "Les files 1 i 3 són iguals, i també la 2 i la 4. Per això el tros «fila vermella, mitja volta, fila groga, mitja volta» va dins d'un <b>bucle gran</b> que es repeteix 2 vegades. Un bucle dins d'un altre bucle!|Las filas 1 y 3 son iguales, y también la 2 y la 4. Por eso el trozo «fila roja, media vuelta, fila amarilla, media vuelta» va dentro de un <b>bucle grande</b> que se repite 2 veces. ¡Un bucle dentro de otro bucle!" },
        { k: 'Compte!|¡Cuidado!', t: 'Cap on gires?|¿Hacia dónde giras?', demo: { w: { map: ['>.....', '......'], target: ['.yyyy.', '.uuuu.'] }, prog: TP('4{ f paint:y } 2{ f l }'), speed: 900 },
          x: "Aquí en Bit gira a l'esquerra al final de la fila… i surt del mapa! Abans de programar la mitja volta, mira <b>on és la fila següent</b>. Si el mosaic baixa, una mitja volta és a la dreta i la següent, a l'esquerra.|Aquí Bit gira a la izquierda al final de la fila… ¡y se sale del mapa! Antes de programar la media vuelta, mira <b>dónde está la fila siguiente</b>. Si el mosaico baja, una media vuelta es a la derecha y la siguiente, a la izquierda.",
          bad: 'Girar sempre cap al mateix costat al final de cada fila.|Girar siempre hacia el mismo lado al final de cada fila.', good: "Mirar on és la fila següent: la dreta i l'esquerra s'alternen.|Mirar dónde está la fila siguiente: la derecha y la izquierda se alternan." }
      ] },
      { k: 'seq', ph: 'mans', q: 'Abans de programar, cal un pla. <b>Ordena els passos</b> per fer un mosaic.|Antes de programar, hace falta un plan. <b>Ordena los pasos</b> para hacer un mosaico.',
        items: ['Mirar el mosaic i comptar les files|Mirar el mosaico y contar las filas', 'Buscar les files que són iguals|Buscar las filas que son iguales', 'Programar una fila amb un bucle|Programar una fila con un bucle', 'Afegir la mitja volta per canviar de fila|Añadir la media vuelta para cambiar de fila', 'Provar-lo i millorar-lo|Probarlo y mejorarlo'],
        ex: 'Primer el pla, després els blocs: així es <b>descompon</b> un problema gran.|Primero el plan, después los bloques: así se <b>descompone</b> un problema grande.' },
      { k: 'quiz', ph: 'mans', q: 'Mira aquest mosaic:<br>🟥🟨🟥🟨<br>🟦🟦🟦🟦<br>🟥🟨🟥🟨<br>🟦🟦🟦🟦<br><b>Quines files són iguals?</b>|Mira este mosaico:<br>🟥🟨🟥🟨<br>🟦🟦🟦🟦<br>🟥🟨🟥🟨<br>🟦🟦🟦🟦<br><b>¿Qué filas son iguales?</b>',
        opts: ['La 1 i la 3, i la 2 i la 4|La 1 y la 3, y la 2 y la 4', 'La 1 i la 2|La 1 y la 2', 'Totes són diferents|Todas son diferentes'], a: 0,
        ex: "Dues files que es repeteixen: el tros «fila 1 + fila 2» es pot fer 2 vegades amb un bucle.|Dos filas que se repiten: el trozo «fila 1 + fila 2» se puede hacer 2 veces con un bucle." },
      { k: 'unplug', ph: 'mans', ico: '🎨', title: 'Mosaic de casa|Mosaico de casa', t: 'Feu un mosaic petit amb el que tingueu a casa: papers de colors, peces de construcció, taps o llegums.|Haced un mosaico pequeño con lo que tengáis en casa: papeles de colores, piezas de construcción, tapones o legumbres.',
        steps: ['Dibuixeu una quadrícula de 4 × 4 en un full.|Dibujad una cuadrícula de 4 × 4 en una hoja.',
          'Decidiu el patró de les files: per exemple, la fila A vermella i groga i la fila B blava.|Decidid el patrón de las filas: por ejemplo, la fila A roja y amarilla y la fila B azul.',
          'Escriviu el programa amb paraules: «fila A, mitja volta, fila B, mitja volta… 2 vegades».|Escribid el programa con palabras: «fila A, media vuelta, fila B, media vuelta… 2 veces».',
          "L'altra persona omple el mosaic seguint només el programa. Ha quedat igual que el vostre pla?|La otra persona rellena el mosaico siguiendo solo el programa. ¿Ha quedado igual que vuestro plan?"] },
      { k: 'parsons', ph: 'prova', q: 'Dues files de colors. <b>Ordena els blocs</b> i executa el programa.|Dos filas de colores. <b>Ordena los bloques</b> y ejecuta el programa.',
        w: { map: ['>.....', '......'], target: ['.rrrr.', '.gggg.'] }, pool: TP('4{ f paint:r } f r f r 4{ f paint:g }'), sol: TP('4{ f paint:r } f r f r 4{ f paint:g }'), hint: 'Primer la fila de dalt (vermella), després la mitja volta i al final la fila de sota.|Primero la fila de arriba (roja), después la media vuelta y al final la fila de abajo.' },
      { k: 'spot', ph: 'investiga', q: 'Aquest mosaic no s\'acaba: en Bit surt del mapa a la segona fila. <b>Toca el bloc equivocat.</b>|Este mosaico no se termina: Bit se sale del mapa en la segunda fila. <b>Toca el bloque equivocado.</b>',
        w: { map: ['>.....', '......'], target: ['.yyyy.', '.yyyy.'] }, prog: TPX('4{ f paint:y } f r f l! 4{ f paint:y }'), ex: "És l'últim gir de la mitja volta: amb dreta i esquerra, en Bit torna a mirar cap a la dreta. Per fer mitja volta calen dos girs iguals.|Es el último giro de la media vuelta: con derecha e izquierda, Bit vuelve a mirar hacia la derecha. Para dar media vuelta hacen falta dos giros iguales." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Fes de rajola! Quan sentis <b>vermell</b>, ajup-te; <b>groc</b>, salta; <b>blau</b>, aplaudeix. Seguiu el patró «vermell, groc, blau» 3 vegades, cada cop més de pressa!|¡Haz de baldosa! Cuando oigas <b>rojo</b>, agáchate; <b>amarillo</b>, salta; <b>azul</b>, aplaude. Seguid el patrón «rojo, amarillo, azul» 3 veces, ¡cada vez más deprisa!" },
      { k: 'build', ph: 'repte', q: 'La primera franja del mosaic: <b>5 rajoles verdes</b>. Toca el bloc Pinta per triar el color. Màxim <b>3 blocs</b>.|La primera franja del mosaico: <b>5 baldosas verdes</b>. Toca el bloque Pinta para elegir el color. Máximo <b>3 bloques</b>.',
        w: { map: ['>.....', '......'], target: ['.ggggg', '......'] }, pal: ['fwd', 'left', 'right', 'rep', 'paint'], sol: TP('5{ f paint:g }'), max: 3, hint: "Dins del bucle: Endavant i Pinta. Quantes rajoles hi ha?|Dentro del bucle: Adelante y Pinta. ¿Cuántas baldosas hay?" },
      { k: 'build', ph: 'repte', q: 'Dues franges: la de dalt <b>blava</b> i la de sota <b>groga</b>. Recorda la mitja volta! Màxim <b>10 blocs</b>.|Dos franjas: la de arriba <b>azul</b> y la de abajo <b>amarilla</b>. ¡Recuerda la media vuelta! Máximo <b>10 bloques</b>.',
        w: { map: ['>.....', '......'], target: ['.uuuu.', '.yyyy.'] }, pal: ['fwd', 'left', 'right', 'rep', 'paint'], sol: TP('4{ f paint:u } 2{ f r } 4{ f paint:y }'), max: 10, hint: "Tros 1: la fila blava. Tros 2: la mitja volta (Endavant, Gira a la dreta, dues vegades). Tros 3: la fila groga.|Trozo 1: la fila azul. Trozo 2: la media vuelta (Adelante, Gira a la derecha, dos veces). Trozo 3: la fila amarilla." },
      { k: 'quiz', ph: 'repte', q: 'El mosaic de la plaça té 4 files: vermella, groga, vermella, groga. Quantes vegades s\'ha de repetir el tros «fila vermella, mitja volta, fila groga, mitja volta»?|El mosaico de la plaza tiene 4 filas: roja, amarilla, roja, amarilla. ¿Cuántas veces se tiene que repetir el trozo «fila roja, media vuelta, fila amarilla, media vuelta»?',
        opts: ['2', '4', '1'], a: 0, ex: "Cada tros pinta 2 files. Per a 4 files, 2 vegades.|Cada trozo pinta 2 filas. Para 4 filas, 2 veces." },
      { k: 'build', ph: 'repte', q: 'El gran mosaic de la plaça! Ja tens el <b>bucle gran</b> preparat: toca a dins i posa-hi el tros de les dues files.|¡El gran mosaico de la plaza! Ya tienes el <b>bucle grande</b> preparado: toca dentro y pon el trozo de las dos filas.',
        w: { map: ['>.....', '......', '......', '......', '......'], target: ['.rrrr.', '.yyyy.', '.rrrr.', '.yyyy.', '......'] }, pal: ['fwd', 'left', 'right', 'rep', 'paint'], prog: TP('2{ }'), sol: TP('2{ 4{ f paint:r } 2{ f r } 4{ f paint:y } 2{ f l } }'),
        hint: "A dins: fila vermella, mitja volta cap a la dreta, fila groga i mitja volta cap a l'esquerra. En acabar, en Bit ha de quedar a la vora, mirant a la dreta, com al principi.|Dentro: fila roja, media vuelta hacia la derecha, fila amarilla y media vuelta hacia la izquierda. Al terminar, Bit tiene que quedar en el borde, mirando a la derecha, como al principio." },
      { k: 'create', ph: 'crea', name: 'El meu mosaic|Mi mosaico', q: '<b>Projecte final de la unitat!</b> Dissenya i pinta el teu propi mosaic a la plaça. Primer fes el pla: quantes files, de quins colors i quines són iguals. Després, programa\'l amb bucles.|<b>¡Proyecto final de la unidad!</b> Diseña y pinta tu propio mosaico en la plaza. Primero haz el plan: cuántas filas, de qué colores y cuáles son iguales. Después, prográmalo con bucles.',
        crit: ['Fa servir almenys un bucle|Usa al menos un bucle', 'Té almenys 8 rajoles pintades|Tiene al menos 8 baldosas pintadas', 'Té almenys 2 colors|Tiene al menos 2 colores'],
        check: p => { if (!bitCountK(p, ['rep'])) return 'El mosaic és bonic! Ara fes-lo amb almenys un bucle.|¡El mosaico es bonito! Ahora hazlo con al menos un bucle.';
          const c = Object.values(bitFinal({ map: ['>.....', '......', '......', '......', '......'] }, p).S.paint);
          if (c.length < 8) return 'El mosaic és massa petit: pinta almenys 8 rajoles.|El mosaico es demasiado pequeño: pinta al menos 8 baldosas.';
          return new Set(c).size >= 2 ? null : 'Fes servir almenys 2 colors diferents.|Usa al menos 2 colores diferentes.'; },
        w: { map: ['>.....', '......', '......', '......', '......'] }, pal: ['fwd', 'left', 'right', 'rep', 'paint'], sol: TP('2{ 4{ f paint:u } 2{ f r } 4{ f paint:g } 2{ f l } }') },
      { k: 'quiz', ph: 'tanca', q: 'Per programar un mosaic, per on comences?|Para programar un mosaico, ¿por dónde empiezas?',
        opts: ['Pel pla: comptar les files i buscar les que són iguals|Por el plan: contar las filas y buscar las que son iguales', 'Posant blocs Pinta fins que surti|Poniendo bloques Pinta hasta que salga', "Pel color que m'agrada més|Por el color que más me gusta"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: 'Al final d\'una fila, què fa <b>Repeteix 2 vegades: Endavant, Gira a la dreta</b>?|Al final de una fila, ¿qué hace <b>Repite 2 veces: Adelante, Gira a la derecha</b>?',
        opts: ['Baixa a la fila de sota i fa mitja volta|Baja a la fila de abajo y da media vuelta', 'Pinta dues rajoles|Pinta dos baldosas', 'Torna al principi del mosaic|Vuelve al principio del mosaico'], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] }
] };
